//! The JavaScript interface, generated by `wasm-bindgen` (see
//! `frontend/src/engine.ts` for the typed wrapper the React app uses).
//!
//! Values cross the boundary as plain JS objects in the same camelCase JSON
//! shape as everywhere else: courses come in through `serde-wasm-bindgen`, and
//! results go out as JSON-compatible objects (`None` becomes `null`). Errors
//! are thrown as JS `Error`s.

use serde::Serialize;
use serde::de::DeserializeOwned;
use wasm_bindgen::prelude::*;

use crate::api;
use crate::course::Course;

fn to_js<T: Serialize>(value: &T) -> Result<JsValue, JsError> {
    value
        .serialize(&serde_wasm_bindgen::Serializer::json_compatible())
        .map_err(|e| JsError::new(&e.to_string()))
}

fn from_js<T: DeserializeOwned>(value: JsValue, what: &str) -> Result<T, JsError> {
    serde_wasm_bindgen::from_value(value).map_err(|e| JsError::new(&format!("invalid {what}: {e}")))
}

/// `blankCourse(): Course`, a starter course.
#[wasm_bindgen(js_name = blankCourse)]
pub fn blank_course() -> Result<JsValue, JsError> {
    to_js(&Course::blank())
}

/// `evaluate(course): Course`, graded and with "what do I need?" solved.
#[wasm_bindgen]
pub fn evaluate(course: JsValue) -> Result<JsValue, JsError> {
    let course: Course = from_js(course, "course")?;
    to_js(&api::evaluate(&course))
}

/// `summaries(courses): (number | null)[]`, each course's percentage.
#[wasm_bindgen]
pub fn summaries(courses: JsValue) -> Result<JsValue, JsError> {
    to_js(&api::summaries(from_js(courses, "courses")?))
}

/// `importCourses(data): Course[]`: validate parsed JSON (one course or a list).
/// Throws if nothing in it is a course.
#[wasm_bindgen(js_name = importCourses)]
pub fn import_courses(data: JsValue) -> Result<JsValue, JsError> {
    let data = from_js(data, "file").map_err(|_| JsError::new(api::NOT_A_COURSE))?;
    to_js(&api::import_courses(data).map_err(JsError::new)?)
}
